        <div class="welcome-visual"><div class="visual-grid"><span v-for="n in 9" :key="n"></span></div><div class="visual-orbit orbit-a"></div><div class="visual-orbit orbit-b"></div><div class="visual-core"><el-icon><MagicStick /></el-icon><strong>CODEX</strong><small>LIVE</small></div></div>
      </section>

      <section v-if="attentionSession && !attentionSession.source_context?.activity" class="attention-banner" role="status"><span class="attention-icon"><el-icon><VideoPlay /></el-icon></span><div><strong>{{ attentionSession.title || '有一个任务正在进行' }}</strong><p>{{ attentionText }}</p></div><div class="attention-actions"><el-button v-if="attentionSession.status === 'paused'" size="small" type="primary" @click="resumeAttention">继续任务</el-button><el-button v-else-if="['running','planned','waiting_confirmation'].includes(attentionSession.status)" size="small" type="warning" plain @click="pauseAttention">暂停任务</el-button><el-button size="small" plain @click="openAttention">查看详情</el-button></div></section>

      <div class="dashboard-freshness" :class="{ stale: runtimeError }"><el-icon><component :is="runtimeError ? 'Warning' : 'CircleCheck'" /></el-icon><span>{{ freshnessText }}</span><small v-if="runtimeError">{{ runtimeError }}</small></div>

      <section v-if="firstRunVisible" class="first-run-guide" aria-labelledby="first-run-title">
        <div class="first-run-heading"><div><span class="kicker">FIRST 10 MINUTES / 可跳过</span><h3 id="first-run-title">先用起来，再决定要不要接入模型</h3><p>不配置也可以整理素材、导入已有媒体、做本地剪辑和让 Codex 规划任务。需要 AI 生图、生视频或特定文本风格时，再按需补充 URL、Key 和模型。推荐先配置银子 API：站点是 yinziapi.top，访问端点是 api.yinziapi.top/v1；登录后创建 Key，复制完整的 sk- 开头内容粘贴进去。</p></div><el-button text @click="dismissFirstRun">暂时隐藏</el-button></div>
        <div class="first-run-steps">
          <article><span>1</span><div><strong>先看一个示例</strong><p>用一句话创建一个不产生费用的计划，理解任务、节点和成果如何回来。</p><el-button size="small" plain @click="useExample(examples[0])">打开示例</el-button></div></article>
          <article><span>2</span><div><strong>按需接入 AI</strong><p>文本、图片、视频可以分别保存多个候选；推荐从银子 API 开始，配置后 Codex 才能调用对应的生图和视频模型。Key 只保存在本机，配置什么就会解锁什么。</p><div class="first-run-actions"><el-button size="small" type="primary" plain @click="router.push('/ai-config?action=yinzi')">配置银子 API</el-button><el-button size="small" plain @click="router.push('/ai-config?action=yinzi')">查看配置步骤</el-button></div></div></article>
          <article><span>3</span><div><strong>不懂就问 Codex</strong><p>可以把 URL、Key、模型名和备注直接发给 Codex，让它代填配置；也可以随时回到“模型与 Key”修改。</p><el-button size="small" text @click="router.push('/help')">查看帮助</el-button></div></article>
        </div>
        <div class="first-run-footnote">当前配置：文本 {{ onboarding?.active_config_counts?.text || 0 }} · 图片 {{ onboarding?.active_config_counts?.image || 0 }} · 视频 {{ onboarding?.active_config_counts?.video || 0 }}；推荐目录只作参考，真正付费前仍会按当前 Key 重新核对能力和价格。</div>
      </section>

      <section class="metric-grid" aria-label="工作台摘要"><article v-for="metric in metrics" :key="metric.label" class="metric-card"><div class="metric-top"><span>{{ metric.label }}</span><el-icon :class="metric.tone"><component :is="metric.icon" /></el-icon></div><strong>{{ metric.value }}</strong><small>{{ metric.note }}</small></article></section>

      <div class="dashboard-columns" :class="{ 'has-work-activity': activeSession?.source_context?.activity || activeBatch }">
        <section v-if="!activeSession?.source_context?.activity && !activeBatch" class="panel current-panel"><header class="panel-heading"><div><span class="kicker">NOW / 当前进行</span><h3>Codex 正在做什么</h3></div><router-link to="/codex-console">查看全部任务 <el-icon><ArrowRight /></el-icon></router-link></header><template v-if="activeSession"><div class="current-session"><div class="current-session-title"><span :class="['status-dot', statusTone(activeSession.status)]"></span><div><strong>{{ activeSession.title || '未命名任务' }}</strong><p>{{ activeSession.user_goal || 'Codex 正在准备制作目标' }}</p></div><span :class="['status-label', statusTone(activeSession.status)]">{{ statusLabel(activeSession.status) }}</span></div><div class="current-progress"><div><span>{{ progressLabel }}</span><strong>{{ progressPercent === null ? '阶段制' : `${progressPercent}%` }}</strong></div><el-progress v-if="progressPercent !== null" :percentage="progressPercent" :show-text="false" :status="activeSession.status === 'failed' ? 'exception' : 'success'" /><div class="stage-row"><span v-for="stage in stages" :key="stage.label" :class="stage.state"><i></i>{{ stage.label }}</span></div></div><div class="current-footer"><span><el-icon><Clock /></el-icon> {{ relativeTime(activeSession.updated_at) }}</span><el-button size="small" type="primary" plain @click="openAttention">打开任务</el-button></div></div></template><div v-else class="empty-current"><span><el-icon><Sunny /></el-icon></span><strong>现在没有运行中的任务</strong><p>从一句描述开始，Codex 会把计划放在这里持续展示。</p><el-button type="primary" plain @click="router.push('/free-create')">开始一个任务</el-button></div></section>

        <section class="panel latest-panel"><header class="panel-heading"><div><span class="kicker">OUTPUT / 最新产出</span><h3>刚刚生成的成果</h3></div><router-link to="/media-library">打开素材库 <el-icon><ArrowRight /></el-icon></router-link></header><div v-if="latestArtifacts.length" class="latest-grid"><article v-for="item in latestArtifacts.slice(0,4)" :key="item.id" class="latest-card" @click="openArtifact(item)"><div class="latest-media"><img v-if="item.type === 'image' && item.url && !brokenArtifacts.has(item.id)" :src="item.url" :alt="item.title" @error="markArtifactBroken(item.id)" /><video v-else-if="item.type === 'video' && item.url && !brokenArtifacts.has(item.id)" :src="item.url" preload="metadata" muted @error="markArtifactBroken(item.id)" /><div v-else class="latest-fallback"><el-icon><component :is="mediaIcon(item.type)" /></el-icon><span>{{ brokenArtifacts.has(item.id) ? '预览暂不可用' : '等待可预览文件' }}</span></div><span class="latest-type">{{ mediaLabel(item.type) }}</span></div><footer><strong :title="item.title">{{ item.title }}</strong><small>{{ relativeTime(item.created_at) }}</small></footer></article></div><div v-else class="empty-latest"><el-icon><Picture /></el-icon><p>成果会在每一步完成后第一时间出现在这里。</p></div></section>
      </div>

      <div class="dashboard-columns lower-columns">
        <section class="panel chart-panel"><header class="panel-heading"><div><span class="kicker">PULSE / 执行节奏</span><h3>最近 30 分钟的推进速度</h3></div><span class="panel-meta">{{ samples.length ? `${samples.length} 个记录点` : '等待任务开始' }}</span></header><div v-if="samples.length > 1" class="sparkline-wrap"><svg viewBox="0 0 640 180" preserveAspectRatio="none" aria-label="任务推进速度图表"><defs><linearGradient id="speedFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="var(--ui-accent)" stop-opacity=".25" /><stop offset="1" stop-color="var(--ui-accent)" stop-opacity="0" /></linearGradient></defs><path :d="sparklineArea" fill="url(#speedFill)" /><polyline :points="sparklinePoints" fill="none" stroke="var(--ui-accent)" stroke-width="3" vector-effect="non-scaling-stroke" /><circle v-for="point in sparklineCircles" :key="point.key" :cx="point.x" :cy="point.y" r="4" fill="var(--bg-card)" stroke="var(--ui-accent)" stroke-width="2" vector-effect="non-scaling-stroke" /></svg><div class="chart-axis"><span>{{ samples[0]?.at ? new Date(samples[0].at).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }) : '开始记录' }}</span><span>现在</span></div><p class="chart-note">纵轴：每分钟完成步骤数。按实际记录时间显示最近 30 分钟。</p></div><div v-else class="chart-empty"><div class="chart-bars"><i v-for="n in 8" :key="n" :style="{ height: `${18 + n * 4}px` }"></i></div><strong>任务开始后，这里会显示实际推进曲线</strong><span>你可以看出哪些阶段变慢，并回到任务详情调整计划。</span></div></section>

        <section class="panel quick-panel"><header class="panel-heading"><div><span class="kicker">TRY / 使用示例</span><h3>不知道怎么说？照着改</h3></div></header><div class="example-list"><button v-for="example in examples" :key="example.title" type="button" @click="useExample(example)"><span :class="['example-icon', example.tone]"><el-icon><component :is="example.icon" /></el-icon></span><span><strong>{{ example.title }}</strong><small>{{ example.prompt }}</small></span><el-icon><ArrowRight /></el-icon></button></div></section>
      </div>

      <section class="panel recent-panel"><header class="panel-heading"><div><span class="kicker">INDEX / 任务索引</span><h3>最近的任务</h3></div><router-link to="/history">查看历史 <el-icon><ArrowRight /></el-icon></router-link></header><div v-if="recentWork.length" class="recent-table"><div class="recent-row recent-head"><span>任务</span><span>状态</span><span>更新时间</span><span>操作</span></div><button v-for="item in recentWork.slice(0,6)" :key="item.key" class="recent-row" type="button" @click="router.push(item.href)"><span><strong>{{ item.title }}</strong><small>{{ item.goal }}</small></span><span :class="['status-label', statusTone(item.status)]">{{ statusLabel(item.status) }}</span><span>{{ relativeTime(item.updated_at) }}</span><span class="row-action"><el-icon><ArrowRight /></el-icon></span></button></div><div v-else class="table-empty">还没有任务，先从首页开始一个简单目标。</div></section>
    </div>
  </div>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { useRouter } from 'vue-router'
import { useLiveRefresh } from '@/composables/useLiveRefresh'
import { useWorkbenchPage } from '@/composables/useWorkbenchPage'
import WorkActivity from '@/components/orchestration/WorkActivity.vue'
import orchestrationAPI from '@/api/orchestration'
import mediaBatchAPI from '@/api/mediaBatch'
import { normalizeArtifacts } from '@/utils/orchestrationExperience'
import { artifactMediaUrl } from '@/utils/mediaUrl'

const router = useRouter()
const loading = ref(false); const runtimeError = ref(''); const sessions = ref([]); const bundles = ref([]); const batches = ref([]); const batchBundles = ref([]); const samples = ref([]); const lastSuccessfulAt = ref(''); const brokenArtifacts = ref(new Set()); const onboarding = ref(null); const firstRunDismissed = ref(localStorage.getItem('yinzi-first-run-guide-dismissed-v1') === '1'); const shortcutSaving = ref(false); const shortcutHint = ref(''); let timer = null
const firstRunVisible = computed(() => !firstRunDismissed.value && !sessions.value.length && !batches.value.length && Boolean(onboarding.value))
const sampleKey = 'yinzi-dashboard-progress-samples-v1'
try { samples.value = JSON.parse(localStorage.getItem(sampleKey) || '[]').filter((item) => item && Number.isFinite(Number(item.progress))).filter((item) => new Date(item.at).getTime() >= Date.now() - 30 * 60000).slice(-240) } catch (_) {}
const snapshotKey = 'yinzi-dashboard-last-success-v2'
try { const cached = JSON.parse(localStorage.getItem(snapshotKey) || '{}'); sessions.value = cached.sessions || []; bundles.value = cached.bundles || []; batches.value = cached.batches || []; batchBundles.value = cached.batchBundles || []; lastSuccessfulAt.value = cached.saved_at || '' } catch (_) {}
const activeSession = computed(() => {
  const current = sessions.value.find(item => ['draft','running','planned','waiting_confirmation','paused'].includes(item.status))
  if (activeBatch.value && (!current || Date.parse(activeBatch.value.created_at) > Date.parse(current.created_at))) return null
  return current || sessions.value.find(item => item.source_context?.analysis_report) || null
})
const activeBatch = computed(() => batches.value.find(item => ['queued','running','paused','needs_review'].includes(item.status)) || null)
const attentionSession = computed(() => activeSession.value)
const batchArtifacts = computed(() => batchBundles.value.flatMap((batch) => (batch.items || []).filter((item) => item.media_url).map((item) => ({ id: `batch-${item.id}`, type: item.kind, title: item.request?.prompt || batch.title, media_url: item.media_url, created_at: item.completed_at || item.updated_at }))))
const latestArtifacts = computed(() => normalizeArtifacts([...bundles.value.flatMap((bundle) => bundle.artifacts || []), ...batchArtifacts.value].sort((a, b) => new Date(b.created_at || 0) - new Date(a.created_at || 0)).map((item) => ({ ...item, url: artifactMediaUrl(item) }))))
const activeBundle = computed(() => bundles.value.find((bundle) => bundle.session?.id === activeSession.value?.id) || bundles.value[0] || null)
const progressPercent = computed(() => { const nodes = activeBundle.value?.nodes || []; if (!nodes.length) return null; const done = nodes.filter((node) => ['succeeded', 'skipped', 'partial', 'failed', 'cancelled'].includes(node.status)).length; return Math.round(done / nodes.length * 100) })
const progressLabel = computed(() => { if (activeSession.value?.status === 'paused') return '已暂停后续步骤，已提交的模型任务仍可继续收口'; const ordered = [...(activeBundle.value?.nodes || [])].sort((a,b) => new Date(b.updated_at || 0)-new Date(a.updated_at || 0)); const node = ordered.find((item) => item.status === 'running') || ordered.find((item) => ['ready', 'waiting_confirmation'].includes(item.status)); return node?.progress?.message || (['succeeded','partial','failed','cancelled'].includes(activeBundle.value?.session?.status) ? '所有步骤已结束，成果与执行记录已保存' : '') || (activeSession.value?.status === 'waiting_confirmation' ? '计划已准备好，等待你的确认' : '等待 Codex 回报下一步') })
const stages = computed(() => { const nodes = activeBundle.value?.nodes || []; return [['准备', ['intake','research','plan']], ['创作', ['create','edit']], ['检查', ['qa']], ['交付', ['deliver']]].map(([label, phases]) => { const items = nodes.filter(node => phases.includes(node.phase)); return { label, state: items.length && items.every(node => ['succeeded','skipped','partial','failed','cancelled'].includes(node.status)) ? 'done' : items.some(node => node.status === 'running') ? 'current' : '' } }) })
const metrics = computed(() => { const batch = readBatchSummary(); const running = sessions.value.filter((item) => item.status === 'running' || item.status === 'draft' && item.source_context?.activity?.state === 'working').length + batch.running; const queued = sessions.value.filter((item) => ['planned', 'waiting_confirmation'].includes(item.status)).length + batch.queued; const complete = sessions.value.filter((item) => ['succeeded', 'partial'].includes(item.status)).length + batch.completed; const costs = sessions.value.reduce((sum, item) => sum + Number(item.usage?.total_cost_cny || item.usage?.cost_cny || 0), 0); return [{ label: '分析与执行', value: running, note: running ? '有任务持续推进' : '等待新的任务', icon: 'VideoPlay', tone: 'mint' }, { label: '待开始 / 待确认', value: queued, note: queued ? '查看任务了解下一步' : '暂无等待事项', icon: 'Timer', tone: 'amber' }, { label: '已完成', value: complete, note: '可在历史记录查看', icon: 'CircleCheck', tone: 'green' }, { label: '本地已记录费用', value: costs ? `¥${costs.toFixed(2)}` : '等待回执', note: '没有回执时不显示为零', icon: 'Coin', tone: 'blue' }] })
const attentionText = computed(() => attentionSession.value?.status === 'paused' ? '已暂停后续步骤，计划和成果已保存；已提交的上游任务会继续收口。' : `${progressLabel.value}。打开任务查看下一步与成果。`)
const examples = [{ title: '做一张宣传图', prompt: '为我的工作流做一张一图流介绍海报', icon: 'Picture', tone: 'mint' }, { title: '批量整理图片', prompt: '把这个文件夹的图片按人物和场景分类', icon: 'FolderOpened', tone: 'amber' }, { title: '做一段教程视频', prompt: '用清晰步骤介绍如何从 Codex 开始创作', icon: 'VideoCamera', tone: 'blue' }]
function readBatchSummary() { return batches.value.reduce((result, item) => { result.running += Number(item.running) || 0; result.queued += Number(item.queued) || 0; result.completed += Number(item.completed) || 0; return result }, { running: 0, queued: 0, completed: 0 }) }
function statusLabel(status) { return ({ running: '执行中', queued: '准备中', planned: '待开始', waiting_confirmation: '待确认', paused: '已暂停', succeeded: '已完成', completed: '已完成', partial: '部分完成', needs_review: '待核对', failed: '失败', cancelled: '已取消', draft: '准备与分析' })[status] || '待处理' }
function statusTone(status) { return ['succeeded','completed'].includes(status) ? 'success' : ['failed'].includes(status) ? 'danger' : ['paused','waiting_confirmation','planned','partial','needs_review'].includes(status) ? 'warning' : ['running','queued'].includes(status) ? 'active' : 'muted' }
function mediaLabel(type) { return ({ image: '图片', video: '视频', audio: '音频', glb: '3D', model: '3D' })[type] || '文件' }
function mediaIcon(type) { return type === 'video' ? 'VideoPlay' : type === 'audio' ? 'Headset' : type === 'glb' || type === 'model' ? 'Box' : 'Picture' }
function relativeTime(value) { if (!value) return '刚刚'; const diff = Math.max(0, Date.now() - new Date(value).getTime()); if (diff < 60000) return '刚刚'; if (diff < 3600000) return `${Math.floor(diff / 60000)} 分钟前`; if (diff < 86400000) return `${Math.floor(diff / 3600000)} 小时前`; return new Date(value).toLocaleDateString('zh-CN', { month: 'numeric', day: 'numeric' }) }
const recentWork = computed(() => [...sessions.value.map((item) => ({ key: `session-${item.id}`, title: item.title || '未命名任务', goal: item.user_goal || '等待 Codex 写入目标', status: item.status, updated_at: item.updated_at, href: `/codex-console/${item.id}` })), ...batches.value.map((item) => ({ key: `batch-${item.id}`, title: item.title || '批量任务', goal: `${item.total} 项 · ${item.kind === 'video' ? '视频' : '图片'}批次`, status: item.status, updated_at: item.updated_at, href: item.settings?._origin === 'manual' ? '/free-create' : `/batch?batch=${encodeURIComponent(item.id)}` }))].sort((a, b) => new Date(b.updated_at || 0) - new Date(a.updated_at || 0)))
const freshnessText = computed(() => lastSuccessfulAt.value ? `数据更新于 ${new Date(lastSuccessfulAt.value).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit', second: '2-digit' })}${runtimeError.value ? '，当前显示上次成功结果' : ''}` : '正在读取本地工作台')
async function loadDashboard() {
  if (loading.value) return
  loading.value = true
  const errors = []
  try {
    if (!onboarding.value) { try { onboarding.value = await orchestrationAPI.onboarding() } catch (_) {} }
    const [sessionResult,batchResult] = await Promise.allSettled([orchestrationAPI.sessions({limit:20}),mediaBatchAPI.list({limit:30})])
    if (sessionResult.status === 'fulfilled') {
      sessions.value = sessionResult.value?.items || []
      const loaded = await Promise.all(sessions.value.slice(0,6).map(async item => {
        const old = bundles.value.find(bundle => bundle.session?.id === item.id)
        if (old && old._event_id === item.last_event_id && old.session?.version === item.version) return old
        try { return {...await orchestrationAPI.get(item.id,{event_limit:10}),_event_id:item.last_event_id} } catch { errors.push('部分任务详情暂时无法刷新');return old }
      }))
      bundles.value = loaded.filter(Boolean)
    } else errors.push(sessionResult.reason?.message || '编排任务连接失败')
    if (batchResult.status === 'fulfilled') {
      batches.value = batchResult.value?.items || []
      const loaded = await Promise.all(batches.value.slice(0,5).map(async item => {
        const old = batchBundles.value.find(batch => batch.id === item.id)
        if (old && old.updated_at === item.updated_at) return old
        try { return await mediaBatchAPI.get(item.id,{item_page:1,item_page_size:20}) } catch { errors.push('部分批次暂时无法刷新');return old }
      }))
      batchBundles.value = loaded.filter(Boolean)
    } else errors.push(batchResult.reason?.message || '批量队列连接失败')
    if (!errors.length) {
      lastSuccessfulAt.value = new Date().toISOString()
      const done=bundles.value.reduce((sum,bundle)=>sum+(bundle.nodes || []).filter(node=>['succeeded','skipped'].includes(node.status)).length,0)+batches.value.reduce((sum,batch)=>sum+Number(batch.completed || 0),0)
      const previous=samples.value.at(-1)
      if (!previous || Date.now()-Date.parse(previous.at)>=10000) {
        const minutes=previous ? Math.max((Date.now()-Date.parse(previous.at))/60000,1/60) : 1
        samples.value=[...samples.value,{at:lastSuccessfulAt.value,progress:progressPercent.value || 0,completed:done,rate:previous ? Math.max(0,done-previous.completed)/minutes : 0}].filter(item=>Date.parse(item.at)>=Date.now()-30*60000).slice(-240)
        try { localStorage.setItem(sampleKey,JSON.stringify(samples.value)); localStorage.setItem(snapshotKey,JSON.stringify({sessions:sessions.value,bundles:bundles.value,batches:batches.value,batchBundles:batchBundles.value,saved_at:lastSuccessfulAt.value})) } catch { /* storage capacity must not interrupt live progress */ }
      }
    }
    runtimeError.value=errors.join('；')
  } finally { loading.value=false }
}
function dismissFirstRun() { firstRunDismissed.value = true; localStorage.setItem('yinzi-first-run-guide-dismissed-v1', '1') }
function openAttention() { if (attentionSession.value) router.push(`/codex-console/${attentionSession.value.id}`) }
async function pauseAttention() { if (!attentionSession.value) return; try { await orchestrationAPI.pause(attentionSession.value.id, { note: '用户从总览首页暂停' }); await loadDashboard() } catch (error) { ElMessage.error(error?.message || '操作失败，请查看连接状态') } }
async function resumeAttention() { if (!attentionSession.value) return; try { await orchestrationAPI.resume(attentionSession.value.id, { note: '用户从总览首页继续' }); await loadDashboard() } catch (error) { ElMessage.error(error?.message || '操作失败，请查看连接状态') } }
function openArtifact(item) { if (item.url) window.open(item.url, '_blank', 'noopener') }
function markArtifactBroken(id) { brokenArtifacts.value = new Set([...brokenArtifacts.value, id]) }
function useExample(example) { router.push({ path: '/free-create', query: { prompt: example.prompt } }) }
async function addDesktopShortcut() {
  if (shortcutSaving.value) return
  shortcutSaving.value = true
  shortcutHint.value = ''
  try {
    const result = await orchestrationAPI.createDesktopShortcut()
    shortcutHint.value = '已添加到 Windows 桌面，双击会自动启动并打开当前工作台。'
    ElMessage.success('桌面快捷方式已准备好')
    return result
  } catch (error) {
    shortcutHint.value = error?.message || '桌面快捷方式创建失败，请检查安装目录和 Windows 权限。'
    ElMessage.error(shortcutHint.value)
  } finally { shortcutSaving.value = false }
}
function pointFor(index, width = 640, height = 180) { const values = samples.value.map((item) => Math.max(0, Number(item.rate) || 0)); const ceiling = Math.max(1, ...values); const x = values.length <= 1 ? 0 : index / (values.length - 1) * width; const y = height - values[index] / ceiling * (height - 18) - 9; return { x, y } }
const sparklinePoints = computed(() => samples.value.map((_, index) => { const point = pointFor(index); return `${point.x},${point.y}` }).join(' ')); const sparklineCircles = computed(() => samples.value.map((item, index) => { const point = pointFor(index); return { ...point, key: `${item.at}-${index}` } })); const sparklineArea = computed(() => { if (!samples.value.length) return ''; const first = pointFor(0); const last = pointFor(samples.value.length - 1); return `M ${first.x},180 L ${sparklinePoints.value.replaceAll(' ', ' L ')} L ${last.x},180 Z` })
useLiveRefresh(loadDashboard, { active: () => sessions.value.some(item => ['draft','running'].includes(item.status)) || batches.value.some(item => ['running','queued'].includes(item.status)), failed: () => Boolean(runtimeError.value) })
useWorkbenchPage({ refresh: loadDashboard, error: () => runtimeError.value, loading: () => loading.value })
</script>

